const VALLEY_EVENT_TYPES = ["PROSPECT_ADDED_TO_CAMPAIGN","SEND_ANY_NEW_OUTREACH","PROSPECT_RESPONSE","SEND_INTERESTED_RESPONSES","SEND_MIGHT_BE_INTERESTED_RESPONSES","SEND_NOT_INTERESTED_RESPONSES","SEND_COPY_FOR_MESSAGES_AFTER_APPROVAL"];
function valleyEventIdentity(body) {
  if (!body || typeof body !== 'object' || !VALLEY_EVENT_TYPES.includes(body.event_type)) {
    throw new Error('unsupported_valley_event_type');
  }
  const timestamp = body.timestamp || body.message?.timestamp;
  if (typeof timestamp !== 'string' || !/^\d{4}-\d{2}-\d{2}T/.test(timestamp)
    || !Number.isFinite(Date.parse(timestamp))) throw new Error('invalid_valley_timestamp');
  const occurred_at = new Date(timestamp).toISOString();
  if (Date.parse(occurred_at) > Date.now() + 300_000) throw new Error('future_valley_timestamp');
  const prospect = body.prospect?.id || body.prospect?.linkedin_url;
  if (typeof prospect !== 'string' || !prospect || prospect.length > 2048) {
    throw new Error('missing_valley_event_identity');
  }
  // A conversation ID alone is NOT an event ID: multiple replies share it.
  const identity = JSON.stringify([
    'valley-event-v1', body.event_type, occurred_at, prospect,
    body.campaign?.id || body.campaign?.name || '',
    body.message?.message_id || body.conversation?.id || '', body.message_index ?? '',
  ]);
  return { identity, event_type: body.event_type, occurred_at };
}
const fact = valleyEventIdentity($json.body || $json);
const event_key = require('crypto').createHash('sha256').update(fact.identity).digest('hex');
return [{json: {events: [{event_key, event_type: fact.event_type, occurred_at: fact.occurred_at}]}}];
